package org.brightstats.stats;
import java.util.*;
import java.nio.file.*;
import com.google.gson.*;
import org.apache.commons.math3.distribution.NormalDistribution;

public final class AdjustedCopulaChecks {
    private static int checks;
    private static void require(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
    private static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid adjusted-copula model accepted");}catch(IllegalArgumentException expected){checks++;}}
    private static void close(double a,double b){require(Math.abs(a-b)<1e-8*Math.max(1,Math.abs(b)),"Identity differs");}
    public static void main(String[] args)throws Exception{
        var json=new GsonBuilder().serializeSpecialFloatingPointValues().serializeNulls().setPrettyPrinting().create();Path output=Path.of(args[0]);Files.createDirectories(output);var cases=new JsonArray();
        double[] ranked=AdjustedCopula.adjustedScores(new double[]{0,0,1,2});double[] probabilities={.5,.5,.6875,.875};for(int i=0;i<4;i++)close(ranked[i],new NormalDistribution().inverseCumulativeProbability(probabilities[i]));
        Random random=new Random(881);double[][] simple=new double[96][3];for(int row=0;row<simple.length;row++){double w=random.nextGaussian(),error=random.nextGaussian(),x=Math.exp(.5*w+.5*error+.5*random.nextGaussian());simple[row]=new double[]{x,w,1+.8*x-.3*w+.15*x*x-.1*x*w+.4*error};}
        var simpleModel=new AdjustedCopula.Model(List.of("X","W","Y"),List.of(new PlsSem.Edge(0,2),new PlsSem.Edge(1,2)),List.of(new NonlinearPls.Extension(2,new int[]{0,0}),new NonlinearPls.Extension(2,new int[]{0,1})),List.of(new AdjustedCopula.Correction(2,new int[]{0},new int[]{1},new int[0],false)),List.of());
        add(cases,simple,simpleModel,new Bootstrap.Options(40,229,.95),json);add(cases,simple,simpleModel,new Bootstrap.Options(40,669,.9,BootstrapIntervals.Method.BCA,RegressionBootstrap.Convention.STANDARD,true),json);
        double[][] system=new double[240][6];for(int row=0;row<system.length;row++){double z=row%2,w=random.nextGaussian(),u=random.nextGaussian(),v=random.nextGaussian(),p=Math.exp(.3*w+.5*u+.5*random.nextGaussian()),q=Math.exp(.2*w+.3*u+.4*v+.5*random.nextGaussian()),m=1+.4*p-.2*q+.3*w+.4*z+.1*p*q+.1*q*z+.3*u+.2*random.nextGaussian(),y=-1+.7*m+.2*p-.4*w+.2*z+.1*p*m+.3*v+.2*random.nextGaussian();system[row]=new double[]{p,q,w,z,m,y};}
        var paths=List.of(new PlsSem.Edge(0,4),new PlsSem.Edge(1,4),new PlsSem.Edge(2,4),new PlsSem.Edge(3,4),new PlsSem.Edge(4,5),new PlsSem.Edge(0,5),new PlsSem.Edge(2,5),new PlsSem.Edge(3,5));var extensions=List.of(new NonlinearPls.Extension(4,new int[]{0,1}),new NonlinearPls.Extension(4,new int[]{1,3}),new NonlinearPls.Extension(5,new int[]{0,4}));
        for(boolean varying:new boolean[]{false,true}){var model=new AdjustedCopula.Model(List.of("P","Q","W","Z","M","Y"),paths,extensions,List.of(new AdjustedCopula.Correction(4,new int[]{0,1},new int[]{2},new int[]{3},varying),new AdjustedCopula.Correction(5,new int[]{0,4},new int[]{2},new int[]{3},varying)),List.of(new PathProcess.Probe("At Z=0",Map.of(0,1.0,1,1.0,2,0.0,3,0.0,4,1.0)),new PathProcess.Probe("At Z=1",Map.of(0,1.0,1,1.0,2,0.0,3,1.0,4,1.0))));add(cases,system,model,new Bootstrap.Options(40,229,.95),json);var fit=AdjustedCopula.fit(system,model);require(fit.equations().size()==2,"All system equations fitted");require(fit.equations().getFirst().controls().groups().size()==(varying?2:1),"Category control schema");require(fit.effects().stream().noneMatch(effect->effect.source()==3),"Binary derivative omitted");}
        double[][] ties=Matrices.copy(simple);for(var row:ties){row[0]=Math.rint(row[0]*3)/3;row[1]=Math.rint(row[1]*3)/3;}add(cases,ties,simpleModel,new Bootstrap.Options(40,229,.95),json);
        var allEndogenous=new AdjustedCopula.Model(simpleModel.names(),simpleModel.paths(),List.of(),List.of(new AdjustedCopula.Correction(2,new int[]{0,1},new int[0],new int[0],false)),List.of());add(cases,simple,allEndogenous,new Bootstrap.Options(40,229,.95),json);
        reject(()->new AdjustedCopula.Correction(2,new int[]{0},new int[]{0},new int[0],false));reject(()->AdjustedCopula.fit(simple,new AdjustedCopula.Model(simpleModel.names(),simpleModel.paths(),simpleModel.extensions(),List.of(new AdjustedCopula.Correction(2,new int[]{0},new int[0],new int[0],false)),List.of())));reject(()->AdjustedCopula.adjustedScores(new double[]{0,0,1,1}));reject(()->AdjustedCopula.adjustedScores(new double[]{1,Double.NaN,2}));
        double[][] invalid=Matrices.copy(system);invalid[0][3]=2;var binaryModel=new AdjustedCopula.Model(List.of("P","Q","W","Z","M","Y"),paths,extensions,List.of(new AdjustedCopula.Correction(4,new int[]{0,1},new int[]{2},new int[]{3},true)),List.of());reject(()->AdjustedCopula.fit(invalid,binaryModel));
        Thread.currentThread().interrupt();try{AdjustedCopula.fit(simple,simpleModel);throw new AssertionError("Cancellation ignored");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}
        Files.writeString(output.resolve("cases.json"),json.toJson(cases));var receipt=new JsonObject();receipt.addProperty("checks",checks);receipt.addProperty("cases",cases.size());Files.writeString(output.resolve("core.json"),json.toJson(receipt));System.out.println(json.toJson(receipt));
    }
    private static void add(JsonArray cases,double[][] data,AdjustedCopula.Model model,Bootstrap.Options options,Gson json){var result=AdjustedCopula.bootstrap(data,model,options,null);var fit=result.point();require(result.inference().successful()==options.samples(),"Full attempt accounting");require(fit.model().probes().size()>0,"Default probes frozen at point-fit means");require(result.inference().estimates().size()==AdjustedCopula.parameters(fit).size(),"Stable coefficient/effect schema");for(var equation:fit.equations()){double rss=0;for(int row=0;row<data.length;row++){close(equation.predictions()[row]+equation.residuals()[row],data[row][equation.target()]);rss+=equation.residuals()[row]*equation.residuals()[row];}close(rss,equation.residualSumOfSquares());}JsonObject item=new JsonObject();item.add("observations",json.toJsonTree(data));item.add("model",json.toJsonTree(fit.model()));item.add("fit",json.toJsonTree(fit));item.add("bootstrap",json.toJsonTree(result.inference()));item.add("wald",json.toJsonTree(result.wald()));require(result.wald().stream().allMatch(w->w.statistic()!=null&&w.successfulDraws()==40),"Full-rank shared-bootstrap Wald tests");cases.add(item);}
}
